      const rows = keys.map(([k, lab]) => { const lo = Object.assign({}, base), hi = Object.assign({}, base); lo[k] = base[k] * (1 - p.pm); hi[k] = base[k] * (1 + p.pm); return [lab, R('CM-17.3', lo).LCOH, R('CM-17.3', hi).LCOH]; });
