      const st = comp('stack'); if (st) chk(out, 'Components', 'Module rating ≤ electrolyser rating', st.p.modMW, '≤ ' + s.ely.P + ' MW', st.p.modMW <= s.ely.P + 1e-9, 'component', 'MW');
