        const wd = comp('wind'); if (wd && s.supply && s.supply.wind > 0) chk(out, 'Components', 'Site wind within the turbine class (' + wd.name.replace(/.*\((IEC [^)]*)\).*/, '$1') + ')', s.supply.v, '≤ ' + wd.p.iecV + ' m/s', s.supply.v <= wd.p.iecV + 1e-9, 'IEC 61400-1', 'm/s');
