    if (!H2.CASES[p.caseKey]) p.caseKey = 'B';
    if (p.ref) p.ref = (p.ref && typeof p.ref === 'object' && !Array.isArray(p.ref)) ? sanitizeBasis(p.ref, p.caseKey).b : undefined;
    if (p.parked && (typeof p.parked !== 'object' || Array.isArray(p.parked))) delete p.parked;
