    play.onclick = () => { if (timer) { stop(); return; } play.innerHTML = '<span aria-hidden="true">❚❚</span> Pause'; play.setAttribute('aria-pressed', 'true'); timer = setInterval(() => { if (!el.isConnected || el.style.display === 'none' || document.hidden) { stop(); return; } setHour((hour + Number(speed.value)) % 8760); drawPF(); }, 140); };
