  const cleanEq = o => { const d = { q: '', level: 'all', src: 'all', sel: 'CM-4.4', vals: {} }; if (!o || typeof o !== 'object' || Array.isArray(o)) return d;
    const lvl = String(o.level); return { q: typeof o.q === 'string' ? o.q.slice(0, 200) : '', level: lvl === 'all' || (/^\d+$/.test(lvl) && +lvl < H2.LEVELS.length) ? lvl : 'all', src: ['all', 'CM', 'DM'].includes(o.src) ? o.src : 'all', sel: typeof o.sel === 'string' && H2.eq(o.sel) ? o.sel : 'CM-4.4', vals: o.vals && typeof o.vals === 'object' && !Array.isArray(o.vals) ? o.vals : {} }; };
