    'Optimise the electrolyser size (8760 h)': "// Case B supply, vary the number of 5 MW modules and find the lowest LCOH\nconst rows = [['Modules', 'MW', 'CF', 'H2 (t/a)', 'LCOH']];\nlet best = null;\nfor (const n of [12, 16, 20, 24, 28]) {\n  const k = H2.solveSystem(Object.assign({}, H2.CASES.B, { modules: n })).kpi;\n  rows.push([n, n * 5, k.CF.toFixed(3), k.H2_t.toFixed(0), k.LCOH.toFixed(2)]);\n  if (!best || k.LCOH < best.LCOH) best = { n, LCOH: k.LCOH };\n}\ntable(rows);\nprint('Lowest LCOH with ' + best.n + ' modules: ' + best.LCOH.toFixed(2) + ' EUR/kg');",
    'Build a flowsheet in code': "const model = [\n  { type: 'supply', params: { pv: 120, wind: 0, bat: 20, batE: 60, GHI: 2300, lat: 25 } },\n  { type: 'electrolyser', params: { tech: 'PEM', P: 60, minLoad: 0.05, capex: 1300 } },\n  { type: 'compressor', params: { p2: 80 } },\n  { type: 'storage', params: { mode: 'hourly', flex: 24, turndown: 0.5, pmin: 35 } },\n  { type: 'methanol', params: {} },\n  { type: 'economics', params: { WACC: 0.07, other: 15 } }\n];\nconst r = H2.runFlowsheet(model);\nr.stream.notes.forEach(n => print(n));",
