    const bar = h('ol', { class: 'wiz-steps cw-steps', 'aria-label': 'Equipment' }), left = h('div', { class: 'cw-left' }), right = h('div', { class: 'cw-right' }), prev = h('div', { class: 'cw-prev', 'aria-live': 'off' });
    const body = h('div', { class: 'cw' }, bar, h('div', { class: 'cw-body' }, left, right), prev);
