    const back = h('button', { type: 'button', class: 'btn' }, '← Back'), next = h('button', { type: 'button', class: 'btn' }, 'Next →');
    back.onclick = guard(back, () => go(k - 1)); next.onclick = guard(next, () => go(k + 1));
