      const cardFor = (c, label, sub) => { const on = c ? cur && cur.id === c.id : !cur;
        return h('button', { type: 'button', class: 'cw-card' + (on ? ' on' : ''), 'aria-pressed': on ? 'true' : 'false', 'data-id': c ? c.id : 'generic', onclick: () => { st.setComp(c ? clone(c) : null); touch(); render(); } },
          h('b', null, label || c.name), h('span', { class: 'k' }, sub || (c ? A.compKey(c) : '')), c ? h('span', { class: 'm' }, c.builtin === false ? 'my library' : 'Hasim library', c.tech ? ' · ' + c.tech : '') : null); };
      if (cfg.generic !== false) list.appendChild(cardFor(null, cfg.genericLabel || 'Generic – use the block values', cfg.genericSub || 'no library component; the block parameters are used and the assessment uses the Hasim default'));
      const all = A.libAll(st.slot);
      all.forEach(c => list.appendChild(cardFor(c)));
