      if (st.sizes && st.sizes.length) {
        const f = h('div', { class: 'cw-sizes', role: 'group', 'aria-label': 'Size in this ' + (cfg.kind || 'model') }, h('div', { class: 'ced-h' }, 'Size in this ' + (cfg.kind || 'model')));
        st.sizes.forEach(sz => { const id = A.uid('cws'); const inp = h('input', { id, value: sz.get() == null ? '' : sz.get(), inputmode: 'decimal', autocomplete: 'off', 'aria-label': sz.label, disabled: !LIC.can('edit') || null });
          inp.onchange = () => { const r = A.checkNumber(inp.value, { min: sz.min, max: sz.max, int: sz.int, unit: sz.unit, current: sz.get() });
            if (!r.ok) { A.setFieldError(inp, r.msg); return; } A.setFieldError(inp, null); if (inp.value !== String(r.v)) inp.value = String(r.v); sz.set(r.v); touch(); infoBox.textContent = st.info ? st.info() : ''; };
          f.appendChild(h('div', { class: 'ced-row' }, h('label', { for: id }, sz.label, sz.unit ? h('span', { class: 'u' }, ' [' + sz.unit + ']') : null), inp)); });
        const infoBox = h('div', { class: 'muted small' }, st.info ? st.info() : ''); f.appendChild(infoBox); right.appendChild(f);
      }
      if (cur) {
        right.appendChild(h('div', { class: 'cw-comp-h' }, h('div', null, h('b', null, cur.name), ' ', badge(cur)), h('div', { class: 'row' },
          cur.modified && A.libFind(cur.id) ? h('button', { type: 'button', class: 'btn sm', onclick: () => { st.setComp(A.libFind(cur.id)); touch(); render(); } }, 'Reset to library values') : null,
          h('button', { type: 'button', class: 'btn sm', disabled: !LIC.can('edit') || null, onclick: () => saveAs(cur, c2 => { st.setComp(c2); touch(); render(); }) }, A.iconEl('save', 13), 'Save as my component…'))));
        right.appendChild(h('p', { class: 'muted small', style: 'margin:2px 0 8px' }, (cur.tech || '') + (cfg.editNote ? ' – ' + cfg.editNote : ' – edit a value to use it in this ' + (cfg.kind || 'model') + '; the library stays unchanged.')));
        right.appendChild(A.compEditor(cur, () => { touch(); const hd = right.querySelector('.cw-comp-h .chip'); if (hd) hd.replaceWith(badge(cur)); }));
      } else right.appendChild(h('div', { class: 'okbox' }, cfg.genericNote || 'No component selected: the block keeps its own parameters, and the impact assessment uses the default Hasim component of this type.'));
      if (k === 0) back.setAttribute('aria-disabled', 'true'); else back.removeAttribute('aria-disabled');
