    A.dialog({ title: 'Save as my component', body: [h('p', null, 'The component with its current values is added to your library (Tools ▸ Component library) and can be used in every model and project.'), h('label', { for: nid }, 'Name'), inp],
      buttons: [{ label: 'Save', pri: true, fn: () => { const x = A.libAdd(c, inp.value); if (!x) return false; notify('“' + x.name + '” saved in your component library.'); done(x); } }, { label: 'Cancel' }] });
